$ErrorActionPreference='Stop'
$helpers=Get-Content (Join-Path $PSScriptRoot 'windows-smoke.ps1') -Raw
Invoke-Expression $helpers.Substring(0,$helpers.IndexOf('$exe ='))
Add-Type -AssemblyName System.Drawing
Add-Type @'
using System;
using System.Runtime.InteropServices;
public static class InteractiveUI {
 [DllImport("user32.dll")] static extern IntPtr SendMessageTimeout(IntPtr h,uint message,IntPtr wp,IntPtr lp,uint flags,uint ms,out UIntPtr result);
 [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h,int n);
 [DllImport("user32.dll")] static extern IntPtr GetPropA(IntPtr h,string key);
 [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr h);
 [DllImport("user32.dll")] static extern bool ClientToScreen(IntPtr h,ref Point p);
 [DllImport("user32.dll")] static extern bool SetCursorPos(int x,int y);
 [DllImport("user32.dll")] static extern void mouse_event(uint flags,uint x,uint y,uint data,UIntPtr extra);
 [StructLayout(LayoutKind.Sequential)] struct Point {public int x,y;}
 public static int Stat(IntPtr h,string key){return GetPropA(h,"MathomirLayer_"+key).ToInt32()-1;}
 public static long Send(IntPtr h,uint message,int wp,IntPtr lp){UIntPtr result;if(SendMessageTimeout(h,message,(IntPtr)wp,lp,2,5000,out result)==IntPtr.Zero)throw new Exception("Control did not respond");return (long)result.ToUInt64();}
 public static long Probe(IntPtr h,int kind,int arg){return Send(h,0x8000+156,kind,(IntPtr)arg);}
 public static void Drag(IntPtr frame,IntPtr view,int x,int y,int endX,int endY){SetForegroundWindow(frame);Point a=new Point{x=x,y=y},b=new Point{x=endX,y=endY};ClientToScreen(view,ref a);ClientToScreen(view,ref b);SetCursorPos(a.x,a.y);System.Threading.Thread.Sleep(100);mouse_event(2,0,0,0,UIntPtr.Zero);System.Threading.Thread.Sleep(80);try{for(int i=1;i<=5;i++){SetCursorPos(a.x+(b.x-a.x)*i/5,a.y+(b.y-a.y)*i/5);System.Threading.Thread.Sleep(60);}}finally{mouse_event(4,0,0,0,UIntPtr.Zero);}System.Threading.Thread.Sleep(150);}
}
'@
function Check($ok,$why){if(!$ok){throw $why}}
function Capture($h,$name){$r=[MathomirUiProbe]::WindowRect($h);$b=New-Object Drawing.Bitmap ($r.Right-$r.Left),($r.Bottom-$r.Top);$g=[Drawing.Graphics]::FromImage($b);try{$g.CopyFromScreen($r.Left,$r.Top,0,0,$b.Size);$b.Save((Join-Path $folder $name))}finally{$g.Dispose();$b.Dispose()}}
function Command($id){[MathomirUiProbe]::Send($main,273,$id)|Out-Null}
function Dialog($command,$title){[MathomirUiProbe]::PostMessage($main,273,[IntPtr]$command,[IntPtr]::Zero)|Out-Null;for($i=0;$i -lt 50;$i++){Start-Sleep -Milliseconds 100;$d=[MathomirUiProbe]::Window($app.Id,$title);if($d -ne [IntPtr]::Zero){return $d}};throw "Dialog did not open: $title"}
function CloseDialog($d,$id=1){[MathomirUiProbe]::PostMessage($d,273,[IntPtr]$id,[IntPtr]::Zero)|Out-Null;for($i=0;$i -lt 40;$i++){Start-Sleep -Milliseconds 100;if(![MathomirUiProbe]::IsWindowVisible($d)){return}};throw 'Dialog did not close'}
function SaveDoc {Command 0xE103;return [xml](Get-Content $script:fixture -Raw)}
function Load($name,$xml){$script:fixture=Join-Path $folder ("interactive-$name.mom");$xml|Set-Content $fixture -Encoding ascii;[MathomirUiProbe]::OpenFile($main,$fixture);Start-Sleep -Milliseconds 350;[MathomirUiProbe]::Send($view,273,32775)|Out-Null;[MathomirUiProbe]::Send($view,276,4)|Out-Null;for($i=0;$i -lt 10;$i++){[MathomirUiProbe]::Send($view,277,2)|Out-Null}}
function Reopen($name){$copy=Join-Path $folder ("interactive-$name.mom");Copy-Item $fixture $copy;[MathomirUiProbe]::OpenFile($main,$copy);$script:fixture=$copy;Start-Sleep -Milliseconds 400}
function PickObjects($mask){[InteractiveUI]::Probe($view,8,$mask)|Out-Null}
function SetField($dialog,$id,$text){[MathomirUiProbe]::SetText([MathomirUiProbe]::Child($dialog,$id),[string]$text)}
function Place($x=100,$y=100){[MathomirUiProbe]::Mouse($view,512,0,$x,$y);[MathomirUiProbe]::Mouse($view,513,1,$x,$y);[MathomirUiProbe]::Mouse($view,514,0,$x,$y);[MathomirUiProbe]::Send($view,258,27)|Out-Null;[MathomirUiProbe]::Mouse($view,512,0,850,40);Start-Sleep -Milliseconds 800}
function Slider($d,$id,$position){$s=[MathomirUiProbe]::Child($d,$id);[InteractiveUI]::Send($s,1029,1,[IntPtr]$position)|Out-Null;[InteractiveUI]::Send($d,276,5,$s)|Out-Null;Start-Sleep -Milliseconds 700}
function Black($x,$y,$w,$h){return [MathomirUiProbe]::CountColor($view,$x,$y,$w,$h,0)}
function HoverRoot($doc,$i){$o=$doc.mathomir.ChildNodes[$i];$type=if($o.HasAttribute('type')){[int]$o.type}else{[int]$o.t};$x=[int]$o.X+$(if($type -eq 2){20}else{5});$y=[int]$o.Y-$(if($type -eq 1){5}else{0});[MathomirUiProbe]::Mouse($view,512,0,$x,$y);$target=[InteractiveUI]::Probe($view,4,0);Check ($target -eq $i+1) "Wrong object hovered: $target instead of $($i+1)";return @([InteractiveUI]::Stat($view,'Left'),[InteractiveUI]::Stat($view,'Top'),[InteractiveUI]::Stat($view,'Right'),[InteractiveUI]::Stat($view,'Bottom'))}
function MoveRoot($doc,$i,$dx,$dy){$r=HoverRoot $doc $i;$x=[InteractiveUI]::Stat($view,'CenterX');$y=[InteractiveUI]::Stat($view,'CenterY');Check ($x -ge 0) 'Connected object has no middle grip';[InteractiveUI]::Drag($main,$view,$x,$y,($x+$dx),($y+$dy));return SaveDoc}
function OnEdge($point,$r){return $point.x -ge $r[0]-2 -and $point.x -le $r[2]+2 -and $point.y -ge $r[1]-2 -and $point.y -le $r[3]+2 -and [Math]::Min([Math]::Min([Math]::Abs($point.x-$r[0]),[Math]::Abs($point.x-$r[2])),[Math]::Min([Math]::Abs($point.y-$r[1]),[Math]::Abs($point.y-$r[3]))) -le 3}
function Attached($doc,$source=0,$target=1,$connector=2){$line=$doc.mathomir.ChildNodes[$connector];$points=@(ShaderPoints $line);$a=HoverRoot $doc $source;$b=HoverRoot $doc $target;Check (OnEdge $points[0] $a) 'Connector source is detached';Check (OnEdge $points[1] $b) 'Connector target is detached';return $points}
$exe=(Resolve-Path source/build/Mathomir.exe).Path;$folder=Split-Path $exe
$env:MATHOMIR_PLACEMENT_DIAGNOSTICS='1';$env:MATHOMIR_DIAGNOSTIC_STARTUP='1'
$app=Start-Process $exe -WorkingDirectory $folder -PassThru
try{
 Start-Sleep -Seconds 2;$app.Refresh();$main=$app.MainWindowHandle;Check ($main -ne [IntPtr]::Zero) 'App did not start';[InteractiveUI]::ShowWindow($main,3)|Out-Null;$view=[MathomirUiProbe]::Child($main,0xE900)
 # Real graph editor, native slider controls, live rendered curve, persistence and Undo.
 Load 'sliders' '<?xml version="1.0"?><mathomir></mathomir>';$d=Dialog 33106 'Relations and parametric curves';SetField $d 1423 'y=a*x';[MathomirUiProbe]::Send($d,273,1439)|Out-Null;Check ([MathomirUiProbe]::IsWindowEnabled([MathomirUiProbe]::Child($d,1))) 'Graph rejected a parameter';CloseDialog $d;Place;Start-Sleep -Seconds 1;$before=Black 160 120 180 390
 $d=Dialog 33108 'Graph parameter sliders';Slider $d 1510 800;$after=Black 160 120 180 390;Check ([Math]::Abs($after-$before) -gt 25) "Slider did not change the live graph: $before -> $after";Capture $main 'interactive-sliders-live.png';CloseDialog $d;$s=SaveDoc
 Check ([double]$s.SelectSingleNode('//sliders').a -eq 3) 'Slider value not saved';Check ($s.SelectNodes('//var[@t="a"] | //elm[@tp="1"][@tx="a"]').Count -gt 0) 'Graph parameter was replaced by a literal'
 Command 0xE12B;$s=SaveDoc;Check ([double]$s.SelectSingleNode('//sliders').a -eq 1) 'Undo did not restore slider values'
 $d=Dialog 33108 'Graph parameter sliders';SetField $d 1514 0;[MathomirUiProbe]::Send($d,273,1501)|Out-Null;Check ([MathomirUiProbe]::Text([MathomirUiProbe]::Child($d,1505)).Contains('minimum')) 'Invalid slider step accepted';SetField $d 1514 .1;Slider $d 1510 800;CloseDialog $d;$s=SaveDoc;Reopen 'sliders-reopened'
 $d=Dialog 33108 'Graph parameter sliders';Check ([double][MathomirUiProbe]::Text([MathomirUiProbe]::Child($d,1511)) -eq 3) 'Slider state lost after reopen';Slider $d 1510 1000;CloseDialog $d 2;$s=SaveDoc;Check ([double]$s.SelectSingleNode('//sliders').a -eq 3) 'Cancel did not restore slider values'
 # Parameters also bind both parametric coordinates and remain editable symbols.
 Load 'parametric' '<?xml version="1.0"?><mathomir></mathomir>';$d=Dialog 33106 'Relations and parametric curves';[MathomirUiProbe]::Send($d,273,1438)|Out-Null;SetField $d 1425 'a*cos(t)';SetField $d 1427 'b*sin(t)';[MathomirUiProbe]::Send($d,273,1439)|Out-Null;CloseDialog $d;Place;$d=Dialog 33108 'Graph parameter sliders';SetField $d 1511 2;SetField $d 1521 3;[MathomirUiProbe]::Send($d,273,1501)|Out-Null;Capture $main 'interactive-parametric-sliders.png';CloseDialog $d;$s=SaveDoc;Check ([double]$s.SelectSingleNode('//sliders').a -eq 2 -and [double]$s.SelectSingleNode('//sliders').b -eq 3) 'Parametric slider values missing';Reopen 'parametric-reopened';[MathomirUiProbe]::Mouse($view,512,0,290,240);Start-Sleep -Milliseconds 150;$d=Dialog 33106 'Relations and parametric curves';Check ([MathomirUiProbe]::Text([MathomirUiProbe]::Child($d,1425)) -eq 'a*cos(t)') 'Parametric coordinates lost their parameter';CloseDialog $d 2
 Write-Output 'Graph sliders passed: live native curve, validation, Undo, Cancel, persistence, symbolic formulas and parametric coordinates.'
 # Each existing group can be a step; these fixtures use plain native text objects.
 $xml='<?xml version="1.0"?><mathomir>';foreach($row in @(@(180,'STEP ONE'),@(260,'STEP TWO'),@(340,'STEP THREE'))){$xml+='<obj type="1" X="180" Y="'+$row[0]+'"><ex fh="100" stxt="1"><var t="'+$row[1]+'" f="00"/></ex></obj>'};$xml+='<obj type="1" X="500" Y="340"><ex stxt="1"><var t="ALWAYS HERE" f="00"/></ex></obj></mathomir>';Load 'steps' $xml;PickObjects 7;$d=Dialog 33109 'Step-by-step sequence';Check ([MathomirUiProbe]::Send([MathomirUiProbe]::Child($d,1470),395,0) -eq 3) 'Step list missing objects';[MathomirUiProbe]::Send([MathomirUiProbe]::Child($d,1470),390,2)|Out-Null;[MathomirUiProbe]::Send($d,273,1471)|Out-Null;Capture $d 'interactive-step-order.png';CloseDialog $d
 Check ([InteractiveUI]::Probe($view,9,1) -eq 1) 'Reveal did not start at the first step';Check ((Black 175 150 220 50) -gt 15 -and (Black 175 230 220 50) -eq 0 -and (Black 175 310 220 50) -eq 0) 'Later steps were painted';Check ((Black 495 310 200 50) -gt 15) 'Reveal hid unrelated content';Capture $main 'interactive-step-first.png'
 [MathomirUiProbe]::Send($view,256,32)|Out-Null;[MathomirUiProbe]::Send($view,258,32)|Out-Null;Check ([InteractiveUI]::Probe($view,9,1) -eq 2) 'Space did not reveal exactly one step';Check ((Black 175 310 220 50) -gt 15 -and (Black 175 230 220 50) -eq 0) 'Step reordering was ignored';Command 33112;Check ([InteractiveUI]::Probe($view,9,1) -eq 1) 'Back failed';[MathomirUiProbe]::Send($view,256,0x23)|Out-Null;Check ([InteractiveUI]::Probe($view,9,1) -eq 3) 'Show all failed';[MathomirUiProbe]::Send($view,256,0x24)|Out-Null;Check ([InteractiveUI]::Probe($view,9,1) -eq 0 -and (Black 175 150 220 50) -eq 0) 'Home did not hide the steps'
 [MathomirUiProbe]::Mouse($view,513,1,200,250);[MathomirUiProbe]::Mouse($view,514,0,200,250);[MathomirUiProbe]::Send($view,258,[int][char]'x')|Out-Null;$s=SaveDoc;Check ($s.mathomir.ChildNodes.Count -eq 4) 'Presentation typing created a document object';Check ($s.SelectNodes('//ex[@steps] | //expr[@steps]').Count -eq 3) 'Save discarded hidden steps or membership';Command 33114;Check ((Black 175 230 220 50) -gt 15) 'Exit did not restore all steps';Reopen 'steps-reopened';Command 33110;Check ([InteractiveUI]::Probe($view,9,1) -eq 1 -and [InteractiveUI]::Probe($view,9,2) -eq 3) 'Saved step sequence did not reopen';Capture $main 'interactive-step-reopened.png';[MathomirUiProbe]::Send($view,256,27)|Out-Null
 $d=Dialog 33109 'Step-by-step sequence';[MathomirUiProbe]::Send($d,273,1472)|Out-Null;[MathomirUiProbe]::Send([MathomirUiProbe]::Child($d,1474),241,0)|Out-Null;CloseDialog $d;$order=SaveDoc;Check ($order.mathomir.ChildNodes[0].SelectSingleNode('./ex | ./expr').order -eq '1') 'Editing the sequence did not change order';Command 0xE12B;$order=SaveDoc;Check ($order.mathomir.ChildNodes[0].SelectSingleNode('./ex | ./expr').order -eq '0') 'Undo did not restore step metadata'
 Write-Output 'Step reveal passed: order editing, native controls, next/back/all/home/escape, hidden content, group isolation, edit protection and full saved content.'
 # Stable references follow both independently moved targets and survive Undo/copy/reopen.
 $xml='<?xml version="1.0"?><mathomir><obj type="2" X="150" Y="180"><objectinfo oid="101"/><dw d="32|0,0;3200,0;3200,1920;0,1920;0,0"/></obj><obj type="2" X="500" Y="300"><objectinfo oid="102"/><dw d="32|0,0;3200,0;3200,1920;0,1920;0,0"/></obj></mathomir>';Load 'connector' $xml;PickObjects 3;$d=Dialog 33115 'Attached connector';Capture $d 'interactive-connector-dialog.png';CloseDialog $d;$s=SaveDoc;Check ($s.mathomir.ChildNodes.Count -eq 3 -and $s.SelectNodes('//connector').Count -eq 1) 'Attached connector not created';$points=Attached $s
 $moved=MoveRoot $s 1 45 25;$new=Attached $moved;Check ([Math]::Abs($new[1].x-$points[1].x)+[Math]::Abs($new[1].y-$points[1].y) -gt 20) 'Connector did not follow the moving target';$r=HoverRoot $moved 1;$size=[MathomirUiProbe]::GripNear($view,$r[2],$r[3],$false);[InteractiveUI]::Drag($main,$view,$size[0],$size[1],($size[0]+35),($size[1]+25));$s=SaveDoc;Attached $s|Out-Null;Command 0xE12B;$s=SaveDoc;Attached $s|Out-Null
 PickObjects 2;Command 32811;$deleted=SaveDoc;Check ($deleted.mathomir.ChildNodes.Count -eq 2 -and $deleted.SelectNodes('//connector').Count -eq 1) 'Target deletion damaged the connector';Command 0xE12B;$s=SaveDoc;Attached $s|Out-Null;Reopen 'connector-reopened';$s=SaveDoc;$s=MoveRoot $s 0 25 -15;Attached $s|Out-Null;Capture $main 'interactive-connector-follow.png'
 PickObjects 7;Check ([InteractiveUI]::Probe($view,2,0) -eq 1) 'Connected diagram copy failed';Place 100 400;$s=SaveDoc;Check ($s.mathomir.ChildNodes.Count -eq 6 -and $s.SelectNodes('//connector').Count -eq 2) 'Connected diagram paste failed';$links=$s.SelectNodes('//connector');Check ($links[0].from -ne $links[1].from -and $links[0].to -ne $links[1].to) 'Copied connector still points to the original objects';$oldLine=$s.mathomir.ChildNodes[2].OuterXml;$s=MoveRoot $s 3 25 -20;Check ($s.mathomir.ChildNodes[2].OuterXml -eq $oldLine) 'Moving copied content changed the original connector';Attached $s 3 4 5|Out-Null
 PickObjects 4;[InteractiveUI]::Probe($view,2,0)|Out-Null;Place 250 100;$s=SaveDoc;Check (!$s.mathomir.ChildNodes[6].SelectSingleNode('./connector')) 'A lone copied connector silently attached to original objects';Capture $main 'interactive-connector-copy.png'
 # The Windows clipboard uses a separate import path from click-to-copy.
 PickObjects 7;Command 0xE122;[MathomirUiProbe]::Mouse($view,512,0,100,100);Command 0xE125;Place 120 120;$os=SaveDoc;Check ($os.mathomir.ChildNodes.Count -eq 10 -and $os.SelectNodes('//connector').Count -eq 3) 'Windows clipboard diagram paste failed';$last=$os.SelectNodes('//connector')[2];$other=$os.SelectNodes('//connector')[0];Check ($last.from -ne $other.from -and $last.to -ne $other.to) 'Ctrl+C/Ctrl+V kept original object references'
 # Cut/paste moves an existing target identity, keeping its original connection.
 $cutXml='<?xml version="1.0"?><mathomir><obj type="2" X="150" Y="180"><dw d="32|0,0;3200,0;3200,1920;0,1920;0,0"/></obj><obj type="2" X="500" Y="300"><dw d="32|0,0;3200,0;3200,1920;0,1920;0,0"/></obj></mathomir>';Load 'connector-cut' $cutXml;PickObjects 3;$d=Dialog 33115 'Attached connector';CloseDialog $d;$s=SaveDoc;$targetId=$s.SelectSingleNode('//connector').to;PickObjects 2;Command 0xE123;$cut=SaveDoc;Check ($cut.mathomir.ChildNodes.Count -eq 2) 'Cut did not remove the target';[MathomirUiProbe]::Mouse($view,512,0,500,280);Command 0xE125;Place 520 290;$cut=SaveDoc;Check ($cut.mathomir.ChildNodes.Count -eq 3 -and $cut.SelectSingleNode('//connector').to -eq $targetId) 'Cut/paste lost the existing target reference';Check ($cut.mathomir.ChildNodes[2].SelectSingleNode('./objectinfo').oid -eq $targetId) 'Cut/paste replaced the target identity';Attached $cut 0 2 1|Out-Null
 # A text target follows the same object-reference path.
 $xml='<?xml version="1.0"?><mathomir><obj type="2" X="150" Y="180"><dw d="32|0,0;3200,0;3200,1920;0,1920;0,0"/></obj><obj type="1" X="500" Y="330"><ex stxt="1"><var t="TARGET" f="00"/></ex></obj></mathomir>';Load 'connector-text' $xml;PickObjects 3;$d=Dialog 33115 'Attached connector';CloseDialog $d;$s=SaveDoc;$s=MoveRoot $s 1 30 15;Attached $s|Out-Null;Capture $main 'interactive-connector-text.png'
 Write-Output 'Connectors passed: native dialog, movement, target resize, Undo, deletion recovery, save/reopen, independent diagram copy, lone-connector copy and text targets.'
}catch{if($main -ne [IntPtr]::Zero){Capture $main 'interactive-failure.png'};throw}finally{if($app -and !$app.HasExited){Stop-Process -Id $app.Id -Force};Remove-Item Env:MATHOMIR_PLACEMENT_DIAGNOSTICS -ErrorAction SilentlyContinue;Remove-Item Env:MATHOMIR_DIAGNOSTIC_STARTUP -ErrorAction SilentlyContinue}
